function coveringWords(words: string[], demands: string[]): string[] {
  const count = (s: string) => {
    const c = new Array(26).fill(0);
    for (const ch of s) c[ch.charCodeAt(0) - 97]++;
    return c;
  };
  const dc = demands.map(count);
  return words.filter(w => {
    const wc = count(w);
    return dc.every(d => d.every((v, i) => wc[i] >= v));
  });
}

