class Solution:
    def coveringWords(self, words: List[str], demands: List[str]) -> List[str]:
        dc = [Counter(d) for d in demands]
        out = []
        for w in words:
            wc = Counter(w)
            if all(wc[c] >= v for d in dc for c, v in d.items()):
                out.append(w)
        return out

