function coveringWords(words: string[], demands: string[]): string[] {
  const need = new Array(26).fill(0);
  for (const d of demands) {
    const c = new Array(26).fill(0);
    for (const ch of d) c[ch.charCodeAt(0) - 97]++;
    for (let i = 0; i < 26; i++) need[i] = Math.max(need[i], c[i]);
  }
  const out: string[] = [];
  for (const w of words) {
    const c = new Array(26).fill(0);
    for (const ch of w) c[ch.charCodeAt(0) - 97]++;
    let ok = true;
    for (let i = 0; i < 26 && ok; i++) if (c[i] < need[i]) ok = false;
    if (ok) out.push(w);
  }
  return out;
}

